private static String printOffset(int offset) {
    int absOffset = Math.abs(offset);
    int hours = absOffset / DateTimeConstants.MILLIS_PER_HOUR;
    int minutes = (absOffset / DateTimeConstants.MILLIS_PER_MINUTE) % 60;
    int seconds = (absOffset / DateTimeConstants.MILLIS_PER_SECOND) % 60;
    int millis = absOffset % DateTimeConstants.MILLIS_PER_SECOND;

    StringBuffer buf = new StringBuffer();
    buf.append(offset >= 0 ? '+' : '-');
    appendDigits(buf, hours);
    buf.append(':');
    appendDigits(buf, minutes);
    if (seconds != 0 || millis != 0) {
        buf.append(':');
        appendDigits(buf, seconds);
        if (millis != 0) {
            buf.append('.');
            appendDigits(buf, millis / 100);
            if (millis % 100 != 0) {
                appendDigits(buf, (millis / 10) % 10);
                if (millis % 10 != 0) {
                    appendDigits(buf, millis % 10);
                }
            }
        }
    }
    return buf.toString();
}
